import java.util.*;
import java.io.*;

public class MinCostMaxFlow {
    static class Edge {
        int u, v;
        int cap, flow, cost;

        Edge(int u, int v, int cap, int flow, int cost) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    int n, m, s, t;
    List<Integer>[] adj;
    List<Edge> edges;
    long[] dist;
    boolean[] inQueue;
    int[] parent;
    long[] minCap;

    public MinCostMaxFlow(int nodes) {
        this.n = nodes;
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        edges = new ArrayList<>();
        dist = new long[n];
        inQueue = new boolean[n];
        parent = new int[n];
        minCap = new long[n];
    }

    void addEdge(int u, int v, int cap, int cost) {
        edges.add(new Edge(u, v, cap, 0, cost));
        edges.add(new Edge(v, u, 0, 0, -cost));
        int m = edges.size();
        adj[u].add(m - 2);
        adj[v].add(m - 1);
    }

    boolean bellmanFord(long[] flowArr, long[] costArr) {
        Arrays.fill(dist, Long.MAX_VALUE);
        Arrays.fill(inQueue, false);
        dist[s] = 0;
        inQueue[s] = true;
        parent[s] = -1;
        minCap[s] = Long.MAX_VALUE;

        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            inQueue[u] = false;
            for (int i : adj[u]) {
                Edge e = edges.get(i);
                if (e.cap > e.flow && dist[e.v] > dist[u] + e.cost) {
                    dist[e.v] = dist[u] + e.cost;
                    parent[e.v] = i;
                    minCap[e.v] = Math.min(minCap[u], e.cap - e.flow);
                    if (!inQueue[e.v]) {
                        q.offer(e.v);
                        inQueue[e.v] = true;
                    }
                }
            }
        }
        if (dist[t] == Long.MAX_VALUE) return false;
        long flow = minCap[t];
        long cost = dist[t];
        int u = t;
        while (u != s) {
            Edge e = edges.get(parent[u]);
            e.flow += flow;
            edges.get(parent[u] ^ 1).flow -= flow;
            u = e.u;
        }
        flowArr[0] = flow;
        costArr[0] = cost;
        return true;
    }

    long[] compute(int s, int t) {
        this.s = s;
        this.t = t;
        long totalFlow = 0;
        long totalCost = 0;
        long[] flowArr = new long[1];
        long[] costArr = new long[1];
        while (bellmanFord(flowArr, costArr)) {
            totalFlow += flowArr[0];
            totalCost += flowArr[0] * costArr[0];
        }
        return new long[]{totalFlow, totalCost};
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());
        int D = Integer.parseInt(br.readLine());

        int totalNodes = n * k + 2;
        MinCostMaxFlow solver = new MinCostMaxFlow(totalNodes);
        int source = n * k;
        int sink = n * k + 1;

        for (int i = 0; i < k; i++) {
            solver.addEdge(i, sink, k, C * i);
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            int x = Integer.parseInt(st.nextToken()) - 1;
            solver.addEdge(source, x * k, 1, 0);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < k; j++) {
                solver.addEdge(i * k + j - 1, i * k + j, k, 0);
            }
        }

        for (int _ = 0; _ < m; _++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int j = 1, cc = D; j <= k; j++, cc += 2 * D) {
                int a = u * k + j - 1;
                int b = v * k + j;
                int c = v * k + j - 1;
                int d = u * k + j;
                for (int i = 1, costVal = cc; i <= k; i++, costVal += 2 * D) {
                    solver.addEdge(a, b, 1, costVal);
                    solver.addEdge(c, d, 1, costVal);
                }
            }
        }
        long[] res = solver.compute(source, sink);
        System.out.println(res[1]);
    }
}

